"""Link final review without hiding its exact pre-link document inputs."""
from pathlib import Path
import sys,shutil,datetime
W=Path(__file__).resolve().parents[2];O=Path(__file__).resolve().parent
sys.path.insert(0,str(W/'tools/parity_audit'))
from common import read,write,sha
D=O/'completion_linkage_01';assert not D.exists();D.mkdir()
rp=O/'groups/G21/reviews/final_coverage/verification_01/review.json';r=read(rp)
assert sha(rp)=='D4E3603B6288F28D860D726C9408B0E07682B21BB9D85E16B293509052209B73'and r['status'].startswith('PASS')and not r['failures']and not r['issues']
cp=read(O/'checkpoint.json');assert cp['report_sha256']==sha(O/'REPORT.md')and cp['handoff_sha256']==sha(O/'HANDOFF.md')
saved={}
for name in ['REPORT.md','checkpoint.json','progress.json','WORKING_CHECKPOINT.json']:
 src=O/name;dest=D/('reviewed_'+name);shutil.copyfile(src,dest);assert sha(src)==sha(dest);saved[name]={'original_path':str(src),'reviewed_snapshot':str(dest),'sha256':sha(dest),'relative_evidence_base':str(O)}
old=(O/'REPORT.md').read_bytes();suffix=('\nFinal independent coverage review passed **2,887 checks with zero failures or issues**. It reconciled the decision registry, all group/peer pins, 161 quests, 1,610 contract rows, 128 deep reviews, the seven-defect/five-repair/two-blocker ledger and every report/handoff link. [Review](groups/G21/reviews/final_coverage/verification_01/review.json). This final paragraph and checkpoint review links are a metadata-only addition; the exact reviewed document inputs are preserved in [completion linkage](completion_linkage_01/addendum.json).\n').encode('utf-8')
(O/'REPORT.md').write_bytes(old+suffix);assert(O/'REPORT.md').read_bytes()==Path(saved['REPORT.md']['reviewed_snapshot']).read_bytes()+suffix
review={'path':str(rp),'sha256':sha(rp),'checks':r['checks'],'failures':0,'issues':0,'scope':'Independent completeness/accounting/provenance, not gameplay certification'}
cp.update(independent_final_coverage_review=review,report_sha256=sha(O/'REPORT.md'),completion_linkage=str(D/'addendum.json'),remaining_final_gates='NONE_WITHIN_QR5_STATIC_SCOPE');write(O/'checkpoint.json',cp)
p=read(O/'progress.json');p['final_coverage_review']=review;p['status']='QR5_COMPLETE_STATIC_SCOPE_WITH_TWO_EXPLICIT_BLOCKERS_AND_LIVE_LIMITS';write(O/'progress.json',p)
q=read(O/'queue.json');m=read(Path(q['working_candidate'])/'package_manifest.json');pro=read(O/'protection_after.json')
write(O/'WORKING_CHECKPOINT.json',{'state':'QR5_COMPLETE','selected':cp['selected'],'new_deep':cp['new_deep'],'deep_total':cp['deep_total'],'remaining':cp['remaining'],'new_confirmed':cp['new_confirmed_defects'],'staged_new_repairs':cp['new_repaired_defects'],'blocked_families':cp['new_blocked_defects'],'new_affected_quests':cp['new_affected_quests'],'canonical_candidate':q['working_candidate'],'canonical_epoch':q['source_epoch_manifest'],'canonical_epoch_sha256':sha(q['source_epoch_manifest']),'archive_sha256':m['archive_sha256'],'zip_sha256':m['zip_sha256'],'installed':'PH3_UNCHANGED','preservation':{'status':pro['status'],'hashes':pro['hashes_verified'],'game_changes':0,'save_changes':0},'final_review':review,'report':str(O/'REPORT.md'),'handoff':str(O/'HANDOFF.md'),'next_batch':cp['next_batch'],'next_action':'QR5 is complete. A future authorized QR6 session continues the exact remaining queue from HANDOFF; do not rerun QR5 baseline/compile/build or reopen resolved cases without new evidence.','restrictions':'No game/deployment/save/fact/release/Git publication occurred or is authorized by this checkpoint.'})
ar=O/'reviews/worker_a/central_supersession/resolution_01/review.json';assert ar.is_file()
write(D/'addendum.json',{'status':'PASS_EXPLICIT_METADATA_ONLY_FINAL_REVIEW_LINKAGE','utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'review':review,'reviewed_input_snapshots':saved,'changes':['REPORT.md unchanged reviewed prefix plus one final-review paragraph','checkpoint.json final-review/linkage keys and updated report hash','progress.json final-review link/status','WORKING_CHECKPOINT.json terminal recovery state'],'current_hashes':{name:sha(O/name)for name in ['REPORT.md','HANDOFF.md','checkpoint.json','progress.json','WORKING_CHECKPOINT.json']},'report_prefix_exact':True,'handoff_unchanged':sha(O/'HANDOFF.md')==cp['handoff_sha256'],'queue_matrix_registry_source_package_game_save_changes':False,'integration_issue_resolution':{'path':str(ar),'sha256':sha(ar),'checks':11},'limits':'Does not extend the independent review to new runtime behavior; none changed. Original review pins remain reproducible against exact preserved snapshots.'})
print({'status':'QR5_COMPLETE','new_deep':cp['new_deep'],'deep_total':cp['deep_total'],'remaining':cp['remaining'],'new_repairs':cp['new_repaired_defects'],'blocked':cp['new_blocked_defects'],'final_coverage_checks':r['checks']})
